<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $money=static fn(float$v):string=>'R$ '.number_format($v,2,',','.');$statusNames=['PENDING'=>'Pendente','RECEIVED'=>'Recebida','CONFIRMED'=>'Confirmada','OVERDUE'=>'Vencida','REFUNDED'=>'Estornada','CANCELED'=>'Cancelada','RECEIVED_IN_CASH'=>'Recebida em dinheiro'];$billingNames=['BOLETO'=>'Boleto','PIX'=>'Pix','CREDIT_CARD'=>'Cartão','UNDEFINED'=>'A definir']; ?>
<div class="actions"><div><span class="status">Financeiro · Cliente</span><h1><?= $escape($customer['name']) ?></h1><p class="meta"><?= $escape($customer['cpf_cnpj']?:'Documento não informado') ?> · <?= $escape($customer['email']?:$customer['mobile_phone']?:$customer['phone']?:'Contato não informado') ?></p></div><div class="actions"><?php if($customer['unit_id']!==null):?><a class="button-primary" href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>/payments/create">Nova cobrança</a><?php endif;?><a href="<?= $escape($basePath) ?>/finance/customers">Voltar aos clientes</a></div></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<div class="dashboard-grid mb-4"><article class="metric-card"><span>Unidade</span><strong><?= $escape($customer['unit_name']?:'Sem unidade') ?></strong></article><article class="metric-card"><span>Contato no CRM</span><strong><?= $escape($customer['crm_name']?:'Não vinculado') ?></strong></article><article class="metric-card"><span>ID no Asaas</span><strong><?= $escape($customer['asaas_customer_id']) ?></strong></article></div>
<?php if($canReconcile&&$customer['unit_id']===null):?><section class="card mb-4"><div class="card-body"><span class="status">Somente Administrador Global</span><h2>Conciliar cliente</h2><p class="meta">Escolha a unidade responsável. Um contato do CRM é sugerido somente quando documento, e-mail ou telefone coincidir.</p><form method="post" action="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>/reconcile"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label for="finance-unit">Unidade <span class="required">*</span></label><select id="finance-unit" name="unit_id" required><option value="">Selecione</option><?php foreach($units as$unit):?><option value="<?= (int)$unit['id'] ?>"><?= $escape($unit['name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="finance-crm">Contato correspondente no CRM</label><select id="finance-crm" name="crm_contact_id"><option value="0">Não vincular agora</option><?php foreach($candidates as$candidate):?><option value="<?= (int)$candidate['id'] ?>"><?= $escape($candidate['name'].' · '.$candidate['unit_name']) ?></option><?php endforeach;?></select><small><?= count($candidates) ?> correspondência(s) segura(s) encontrada(s).</small></div></div><button class="button-primary" type="submit">Confirmar conciliação</button></form></div></section><?php endif;?>
<h2>Cobranças</h2><div class="table-responsive"><table><thead><tr><th>Vencimento</th><th>Descrição</th><th>Forma</th><th>Valor</th><th>Situação</th><th>Documentos</th></tr></thead><tbody><?php if($payments===[]):?><tr><td colspan="6">Nenhuma cobrança encontrada.</td></tr><?php endif;?><?php foreach($payments as$payment):?><tr><td><?= $escape($payment['due_date']?date('d/m/Y',strtotime($payment['due_date'])):'—') ?></td><td><?= $escape($payment['description']?:'Cobrança Asaas') ?></td><td><?= $escape($billingNames[$payment['billing_type']]??$payment['billing_type']??'—') ?></td><td><?= $escape($money((float)$payment['value'])) ?></td><td><span class="connection-badge"><?= $escape($statusNames[$payment['status']]??$payment['status']) ?></span></td><td><?php if($payment['invoice_url']):?><a href="<?= $escape($payment['invoice_url']) ?>" target="_blank" rel="noopener">Fatura</a><?php endif;?><?php if($payment['bank_slip_url']):?> <a href="<?= $escape($payment['bank_slip_url']) ?>" target="_blank" rel="noopener">Boleto</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
